def sigmoid(z):
    return 1/(1+np.exp(-z))

def train_ordinal(X, y, lr=0.01, epochs=800):
    n, d = X.shape

    w = np.zeros(d)
    t1, t2 = 0.0, 1.0

    for _ in range(epochs):
        z = X@w
        p1 = sigmoid(t1 - z)
        p2 = sigmoid(t2 - z)

        gw = np.zeros(d)
        gt1, gt2 = 0.0, 0.0

        for i in range(n):
            if y[i] == 1:
                gw += (1- p1[i])* X[i]
                gt1 -= (1 -p1[i])
            elif y[i] == 2:
                gw += (p1[i]- p2[i]) * X[i]
                gt1 += p1[i]
                gt2 -= (1 -p2[i])
            else:
                gw += p2[i] *X[i]
                gt2 += p2[i]

        w -= lr*gw/n
        t1 -= lr*gt1/n
        t2 -= lr*gt2/n

    return w, t1, t2

def predict_ordinal(X, w, t1, t2):
    z = X @ w
    y_hat = []

    for v in z:
        if v<t1:
            y_hat.append(1)
        elif v <t2:
            y_hat.append(2)
        else:
            y_hat.append(3)

    return np.array(y_hat)

w, t1, t2 = train_ordinal(X_train, y_train)

y_ord = predict_ordinal(X_test, w, t1, t2)

print("Ordinal Accuracy:",
      accuracy_score(y_test, y_ord))

print("Ordinal MAE:",
      mean_absolute_error(y_test, y_ord))

